      html: '<div class="cshell">' + side("Prism", ["Overview", "Revenue", "Users", "Chains", "Reports"], 0) + '<div class="cmain"><div class="rowb head"><div><span class="mu sm">Last 8 weeks</span><span class="h t1">Overview</span></div><span class="segc"><i>7D</i><i class="on">8W</i><i>1Y</i></span></div><div class="kpis k3">' + kpi("Volume", "$412.8M", "+18.4%", "up") + kpi("Fees", "$1.24M", "+9.1%", "up") + kpi("Active wallets", "86,412", "-2.3%", "dn") + "</div>" +
        '<div class="two"><div class="card"><div class="rowb"><b class="h">Weekly volume</b><span class="mu sm">$ millions</span></div><div class="ibars">' + [38, 46, 41, 58, 52, 70, 64, 88].map(function (v, i) { return '<div class="ibw"><i class="ib' + (i === 7 ? " hi" : "") + '" style="height:' + (v * 1.9) + 'px"></i><small class="m mu">W' + (i + 1) + "</small></div>"; }).join("") + '</div></div><div class="card"><b class="h">By chain</b><div class="dn2">' + donut([44, 27, 18, 11]) + legend([["Ethereum", "44%"], ["Base", "27%"], ["Arbitrum", "18%"], ["Other", "11%"]]) + "</div></div></div></div></div>",
      structure: ["Left sidebar: product name, vertical menu with Overview active, and a connected-wallet card.", "Page header with the title and a 7D / 8W / 1Y switch, then three stat cards (volume, fees, active wallets) with their changes coloured by direction.", "Main card: an isometric 3D bar chart of eight weeks. Every bar is a solid block with a front face, a lighter top face and a darker side face; the latest week is in the accent colour. Week labels sit under the bars in the monospace font.", "Side card: a donut chart of volume by chain with a four-row legend."],
